func TestListSessionLogsFiltersAndSortsJSONL(t *testing.T) {
	dir := t.TempDir()
	writeFile(t, filepath.Join(dir, "b.jsonl"), "{}\n")
	writeFile(t, filepath.Join(dir, "a.jsonl"), "{}\n")
	writeFile(t, filepath.Join(dir, "ignore.txt"), "{}\n")
	if err := os.Mkdir(filepath.Join(dir, "dir.jsonl"), 0o755); err != nil {
		t.Fatalf("mkdir: %v", err)
	}

	entries, err := ListSessionLogs(context.Background(), dir)
	if err != nil {
		t.Fatalf("ListSessionLogs: %v", err)
	}
	if len(entries) != 2 {
		t.Fatalf("len(entries) = %d, want 2", len(entries))
	}
	if entries[0].SessionID != "a" || entries[1].SessionID != "b" {
		t.Fatalf("entries = %+v, want sorted a,b", entries)
	}
	if entries[0].Size == 0 || entries[0].ModTime.IsZero() {
		t.Fatalf("entry metadata not populated: %+v", entries[0])
	}
}

func TestWriteAndReplaySessionLog(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "svc-1.jsonl")
	logger := session.NewLogger(dir, "svc-1")
	logger.Emit(agentcore.EventSessionStart, session.SessionStartData{
		Prompt:           "hello",
		SelectedEndpoint: "desk-a",
		Sticky: session.RoutingStickyState{
			KeyPresent: true,
			Assignment: "acquired",
			Reason:     "new sticky lease acquired",
		},
		Utilization: session.RoutingUtilizationState{
			Source:    "llama-server.slots",
			Freshness: "fresh",
		},
	})
	logger.Emit(agentcore.EventSessionEnd, session.SessionEndData{
		Status:           agentcore.StatusSuccess,
		SelectedEndpoint: "desk-a",
		Sticky: session.RoutingStickyState{
			KeyPresent: true,
			Assignment: "acquired",
			Reason:     "new sticky lease acquired",
		},
	})
	if err := logger.Close(); err != nil {
		t.Fatalf("Close: %v", err)
	}

	var raw bytes.Buffer
	if err := WriteSessionLog(context.Background(), path, &raw); err != nil {
		t.Fatalf("WriteSessionLog: %v", err)
	}
	if !strings.Contains(raw.String(), "\"type\": \"session.start\"") {
		t.Fatalf("raw log missing session.start: %s", raw.String())
	}
	if !strings.Contains(raw.String(), "\"selected_endpoint\": \"desk-a\"") {
		t.Fatalf("raw log missing selected_endpoint: %s", raw.String())
	}

	var replay bytes.Buffer
	if err := ReplaySession(context.Background(), path, &replay); err != nil {
		t.Fatalf("ReplaySession: %v", err)
	}
	if !strings.Contains(replay.String(), "Session svc-1") {
		t.Fatalf("replay missing session header: %s", replay.String())
	}
	if !strings.Contains(replay.String(), "Selected endpoint: desk-a") {
		t.Fatalf("replay missing selected endpoint: %s", replay.String())
	}
}

func TestUsageReportDelegatesToSessionAggregation(t *testing.T) {
	dir := t.TempDir()
	logger := session.NewLogger(dir, "usage-1")
	logger.Write(agentcore.Event{
		SessionID: "usage-1",
		Seq:       1,
		Type:      agentcore.EventSessionStart,
		Timestamp: time.Date(2026, 5, 5, 14, 0, 0, 0, time.UTC),
		Data: mustSessionData(t, session.SessionStartData{
			Provider: "openrouter",
			Model:    "gpt-test",
		}),
	})
	logger.Write(agentcore.Event{
		SessionID: "usage-1",
		Seq:       2,
		Type:      agentcore.EventSessionEnd,
		Timestamp: time.Date(2026, 5, 5, 14, 0, 1, 0, time.UTC),
		Data: mustSessionData(t, session.SessionEndData{
			Status: agentcore.StatusSuccess,
			Tokens: agentcore.TokenUsage{
				Input: 10,
				Total: 10,
			},
		}),
	})
	if err := logger.Close(); err != nil {
		t.Fatalf("Close: %v", err)
	}

	report, err := UsageReport(context.Background(), dir, session.UsageOptions{})
	if err != nil {
		t.Fatalf("UsageReport: %v", err)
	}
	if report.Totals.Sessions != 1 || report.Totals.InputTokens != 10 {
		t.Fatalf("totals = %+v, want one 10-token session", report.Totals)
	}
}

func writeFile(t *testing.T, path, content string) {
	t.Helper()
	if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
		t.Fatalf("write %s: %v", path, err)
	}
}

func mustSessionData(t *testing.T, v any) []byte {
	t.Helper()
	data, err := json.Marshal(v)
	if err != nil {
		t.Fatalf("MarshalData: %v", err)
	}
	return data
}

package agentcli_test

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"sync"
	"testing"
	"time"

	fizeau "github.com/DocumentDrivenDX/fizeau"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

type routingChatRequest struct {
	Model string `json:"model"`
}

type countedOpenAIServer struct {
	server          *httptest.Server
	mu              sync.Mutex
	chatCalls       int
	lastModel       string
	responseStatus  int
	modelsStatus    int
	responseModel   string
	responseContent string
	models          []string
	chatDelay       time.Duration
}

func newCountedOpenAIServer(t *testing.T, responseStatus int, responseModel, responseContent string) *countedOpenAIServer {
	t.Helper()
	s := &countedOpenAIServer{
		responseStatus:  responseStatus,
		responseModel:   responseModel,
		responseContent: responseContent,
	}
	s.server = httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		switch r.URL.Path {
		case "/v1/models":
			s.mu.Lock()
			models := append([]string(nil), s.models...)
			responseModel := s.responseModel
			modelsStatus := s.modelsStatus
			s.mu.Unlock()
			if modelsStatus == 0 {
				modelsStatus = http.StatusOK
			}
			if modelsStatus != http.StatusOK {
				w.WriteHeader(modelsStatus)
				_, _ = w.Write([]byte(`{"error":{"message":"models unavailable"}}`))
				return
			}
			if len(models) == 0 {
				if responseModel != "" {
					models = []string{responseModel}
				} else {
					models = []string{"stub-model"}
				}
			}
			w.Header().Set("Content-Type", "application/json")
			payload := struct {
				Data []map[string]string `json:"data"`
			}{Data: make([]map[string]string, 0, len(models))}
			for _, model := range models {
				payload.Data = append(payload.Data, map[string]string{"id": model})
			}
			require.NoError(t, json.NewEncoder(w).Encode(payload))
		case "/v1/chat/completions":
			s.mu.Lock()
			s.chatCalls++
			delay := s.chatDelay
			s.mu.Unlock()
			if delay > 0 {
				time.Sleep(delay)
			}

			defer r.Body.Close()
			var req routingChatRequest
			if err := json.NewDecoder(r.Body).Decode(&req); err == nil {
				s.mu.Lock()
				s.lastModel = req.Model
				s.mu.Unlock()
			}

			if s.responseStatus != http.StatusOK {
				w.WriteHeader(s.responseStatus)
				_, _ = w.Write([]byte(`{"error":{"message":"upstream failed"}}`))
				return
			}

			w.Header().Set("Content-Type", "application/json")
			_, _ = w.Write([]byte(`{
				"id":"chatcmpl-route",
				"object":"chat.completion",
				"created":1712534400,
				"model":"` + s.responseModel + `",
				"choices":[{"index":0,"message":{"role":"assistant","content":"` + s.responseContent + `"},"finish_reason":"stop"}],
				"usage":{"prompt_tokens":8,"completion_tokens":4,"total_tokens":12}
			}`))
		default:
			http.NotFound(w, r)
		}
	}))
	t.Cleanup(s.server.Close)
	return s
}

func (s *countedOpenAIServer) baseURL() string {
	return s.server.URL + "/v1"
}

func (s *countedOpenAIServer) chatCallCount() int {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.chatCalls
}

func (s *countedOpenAIServer) requestedModel() string {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.lastModel
}

func (s *countedOpenAIServer) setModels(models ...string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.models = append([]string(nil), models...)
}

func (s *countedOpenAIServer) setChatDelay(delay time.Duration) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.chatDelay = delay
}

func (s *countedOpenAIServer) setModelsStatus(status int) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.modelsStatus = status
}

func eventDataByType(t *testing.T, events []fizeau.SessionEvent, eventType fizeau.SessionEventType) map[string]any {
	t.Helper()
	for _, e := range events {
		if e.Type != eventType {
			continue
		}
		var payload map[string]any
		require.NoError(t, json.Unmarshal(e.Data, &payload))
		return payload
	}
	t.Fatalf("event %s not found", eventType)
	return nil
}

func latestSessionLogPath(t *testing.T, workDir string) string {
	t.Helper()
	paths, err := filepath.Glob(filepath.Join(workDir, ".fizeau", "sessions", "*.jsonl"))
	require.NoError(t, err)
	require.NotEmpty(t, paths, "expected at least one session log")

	latest := paths[0]
	latestInfo, err := os.Stat(latest)
	require.NoError(t, err)
	for _, path := range paths[1:] {
		info, statErr := os.Stat(path)
		require.NoError(t, statErr)
		if info.ModTime().After(latestInfo.ModTime()) {
			latest = path
			latestInfo = info
		}
	}
	return latest
}

func writeRoutingHistorySession(t *testing.T, workDir, sessionID string, ts time.Time, data fizeau.SessionEndData) {
	t.Helper()
	logDir := filepath.Join(workDir, ".fizeau", "sessions")
