			for _, ev := range result.Events {
				if ev.Metadata["mode"] != "replay" || ev.Metadata["cassette"] != tc.harness || ev.Metadata["test_suite"] != "harness-golden" {
					t.Fatalf("event metadata not echoed for %s event: %#v", ev.Type, ev.Metadata)
				}
