				if tc.harness == "codex" {
					wantOutput = "codex-tool"
				}
				if !strings.Contains(result.ToolResults[0].Output, wantOutput) {
					t.Fatalf("tool result output: got %q, want to contain %q", result.ToolResults[0].Output, wantOutput)
				}
			}
		})
	}
