// This file implements ListModels for the FizeauService service.
// It lives in the root package to avoid import cycles; provider and catalog
// data is injected via ServiceConfig (defined in service.go).
//
// Provider-backed models are discovered through /v1/models. Codex and Claude
// expose a separate harness-native surface backed by PTY/CLI evidence.

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strings"
	"sync"

	"github.com/DocumentDrivenDX/fizeau/internal/compaction"
	"github.com/DocumentDrivenDX/fizeau/internal/harnesses"
	claudeharness "github.com/DocumentDrivenDX/fizeau/internal/harnesses/claude"
	codexharness "github.com/DocumentDrivenDX/fizeau/internal/harnesses/codex"
	geminiharness "github.com/DocumentDrivenDX/fizeau/internal/harnesses/gemini"
	"github.com/DocumentDrivenDX/fizeau/internal/modelcatalog"
	"github.com/DocumentDrivenDX/fizeau/internal/provider/lmstudio"
	"github.com/DocumentDrivenDX/fizeau/internal/provider/omlx"
	"github.com/DocumentDrivenDX/fizeau/internal/provider/openrouter"
	"github.com/DocumentDrivenDX/fizeau/internal/serverinstance"
)

// ListModels returns models matching the filter, with full metadata.
// Empty filter returns all models from every reachable provider.
func (s *service) ListModels(ctx context.Context, filter ModelFilter) ([]ModelInfo, error) {
	if filter.Harness != "" && harnesses.ResolveHarnessAlias(filter.Harness) != "fiz" {
		return s.listModelsForSubprocessHarness(filter), nil
	}

	sc := s.opts.ServiceConfig
	if sc == nil {
		return nil, fmt.Errorf("service: no ServiceConfig provided; pass ServiceOptions.ServiceConfig")
	}

	// Load the model catalog once for cross-referencing.
	cat, _ := modelcatalog.Default() // ignore error: catalog miss is non-fatal

	defaultProviderName := sc.DefaultProviderName()

	names := sc.ProviderNames()

	type indexedModels struct {
		idx    int
		models []ModelInfo
	}
	results := make([]indexedModels, len(names))
	var wg sync.WaitGroup

	for i, name := range names {
		// Apply provider filter.
		if filter.Provider != "" && filter.Provider != name {
			results[i] = indexedModels{idx: i, models: nil}
			continue
		}
		// Apply harness filter: providers are served by the "fiz" harness.
		if filter.Harness != "" && harnesses.ResolveHarnessAlias(filter.Harness) != "fiz" {
			results[i] = indexedModels{idx: i, models: nil}
			continue
		}

		wg.Add(1)
		go func(idx int, providerName string) {
			defer wg.Done()

			entry, ok := sc.Provider(providerName)
			if !ok {
				results[idx] = indexedModels{idx: idx, models: nil}
				return
			}

			isDefaultProvider := providerName == defaultProviderName
			models := listModelsForProvider(ctx, providerName, entry, isDefaultProvider, sc, cat)
			results[idx] = indexedModels{idx: idx, models: models}
		}(i, name)
	}
	wg.Wait()

	// Flatten in stable provider order.
	var out []ModelInfo
	for _, r := range results {
		out = append(out, r.models...)
	}
	return out, nil
}

func (s *service) listModelsForSubprocessHarness(filter ModelFilter) []ModelInfo {
	name := harnesses.ResolveHarnessAlias(filter.Harness)
	cfg, ok := s.registry.Get(name)
	modelIDs := subprocessHarnessModelIDs(name, cfg)
	if !ok || cfg.IsHTTPProvider || cfg.IsLocal || len(modelIDs) == 0 {
		return nil
	}
	if filter.Provider != "" && filter.Provider != name {
		return nil
	}
	cat, _ := modelcatalog.Default()
	catalogRefs := catalogRefsForHarness(cat, name)
	out := make([]ModelInfo, 0, len(modelIDs))
	for i, id := range modelIDs {
		info := ModelInfo{
			ID:             id,
			Provider:       name,
			Harness:        name,
			EndpointName:   name,
			ServerInstance: name,
			Capabilities:   []string{"streaming", "tool_use"},
			Available:      true,
			IsDefault:      cfg.DefaultModel != "" && id == cfg.DefaultModel,
			CatalogRef:     catalogRefs[id],
			RankPosition:   i,
		}
		if cat != nil {
			info.ContextLength, info.ContextSource = resolveContextEvidence(context.Background(), ServiceProviderEntry{}, id, cat)
			info.Cost, info.PerfSignal = catalogCostAndPerf(cat, id)
			info.Power, info.AutoRoutable, info.ExactPinOnly = catalogPowerEligibility(cat, id)
		}
		out = append(out, info)
	}
	return out
}

func subprocessHarnessModelIDs(name string, cfg harnesses.HarnessConfig) []string {
	models := append([]string(nil), cfg.Models...)
	switch name {
	case "claude":
		snapshot := claudeharness.DefaultClaudeModelDiscovery()
		models = appendUniqueModelIDs(models, snapshot.Models...)
		for _, family := range []string{"sonnet", "opus", "haiku"} {
			resolved := claudeharness.ResolveClaudeFamilyAlias(family, snapshot)
			if resolved != family {
				models = appendUniqueModelIDs(models, resolved)
			}
		}
	case "codex":
		snapshot := codexharness.DefaultCodexModelDiscovery()
		models = appendUniqueModelIDs(models, snapshot.Models...)
		for _, family := range []string{"gpt", "gpt-5"} {
			resolved := codexharness.ResolveCodexModelAlias(family, snapshot)
			if resolved != family {
				models = appendUniqueModelIDs(models, resolved)
			}
		}
	case "gemini":
		snapshot := geminiharness.DefaultGeminiModelDiscovery()
		models = appendUniqueModelIDs(models, snapshot.Models...)
		for _, family := range []string{"gemini", "gemini-2.5"} {
			resolved := geminiharness.ResolveGeminiModelAlias(family, snapshot)
			if resolved != family {
				models = appendUniqueModelIDs(models, resolved)
			}
		}
	}
	return models
}

func resolveSubprocessModelAlias(harness, model string) string {
	switch harness {
	case "claude":
		return claudeCLIExecutableModel(model)
	case "codex":
		return codexharness.ResolveCodexModelAlias(model, codexharness.DefaultCodexModelDiscovery())
	case "gemini":
		return geminiharness.ResolveGeminiModelAlias(model, geminiharness.DefaultGeminiModelDiscovery())
	default:
		return model
	}
}

func claudeCLIExecutableModel(model string) string {
	normalized := strings.ToLower(strings.TrimSpace(model))
	switch {
	case normalized == "sonnet" || strings.HasPrefix(normalized, "sonnet-") || strings.HasPrefix(normalized, "claude-sonnet-"):
		return "sonnet"
	case normalized == "opus" || strings.HasPrefix(normalized, "opus-") || strings.HasPrefix(normalized, "claude-opus-"):
		return "opus"
	case normalized == "haiku" || strings.HasPrefix(normalized, "haiku-") || strings.HasPrefix(normalized, "claude-haiku-"):
		return "haiku"
	default:
		return model
	}
}

func appendUniqueModelIDs(values []string, additions ...string) []string {
	for _, value := range additions {
		value = strings.TrimSpace(value)
		if value == "" {
			continue
		}
		found := false
		for _, existing := range values {
			if existing == value {
				found = true
				break
			}
		}
		if !found {
			values = append(values, value)
		}
	}
	return values
}

func catalogRefsForHarness(cat *modelcatalog.Catalog, harness string) map[string]string {
	if cat == nil {
		return nil
	}
	switch harness {
	case "codex":
		return cat.AllConcreteModels(modelcatalog.SurfaceCodex)
	case "claude":
		return cat.AllConcreteModels(modelcatalog.SurfaceClaudeCode)
	case "gemini":
		return cat.AllConcreteModels(modelcatalog.SurfaceGemini)
	default:
		return nil
	}
}

// listModelsForProvider discovers and annotates models for a single provider.
func listModelsForProvider(
	ctx context.Context,
	providerName string,
	entry ServiceProviderEntry,
	isDefaultProvider bool,
	sc ServiceConfig,
	cat *modelcatalog.Catalog,
) []ModelInfo {
	if entry.ConfigError != "" {
		return nil
	}
	// Discover model IDs from the provider.
	discoveries := discoverAndRankModels(ctx, entry, cat)
	if len(discoveries) == 0 {
		return nil
	}

	configuredDefaultModel := entry.Model
	providerType := normalizeServiceProviderType(entry.Type)

	outLen := 0
	for _, discovery := range discoveries {
		outLen += len(discovery.IDs)
	}
	out := make([]ModelInfo, 0, outLen)
	for _, discovery := range discoveries {
		// Build a position map from the ranked list.
		rankPos := make(map[string]int, len(discovery.Ranked))
		for pos, sm := range discovery.Ranked {
			rankPos[sm.ID] = pos
		}

package fizeau

import (
	"context"
	"time"

	"github.com/DocumentDrivenDX/fizeau/internal/routehealth"
	"github.com/DocumentDrivenDX/fizeau/internal/serverinstance"
)

// RouteStatus returns live routing state for configured providers/models.
// It is the operator dashboard view: cooldowns, recent decisions, and
// per-candidate health. Distinct from per-request ResolveRoute.
func (s *service) RouteStatus(ctx context.Context) (*RouteStatusReport, error) {
	s.ensurePrimaryQuotaRefresh(ctx, quotaRefreshAsync)
	sc := s.opts.ServiceConfig
	report := &RouteStatusReport{
		GeneratedAt: time.Now(),
	}
	// ADR-006 §5: populate routing-quality over a recent window
	// (RouteStatusRoutingQualityWindow) regardless of whether a route
	// catalog is configured — the metric reflects Execute traffic, not
	// configured routes.
	if s != nil && s.routingQuality != nil {
		recent := s.routingQuality.snapshotRecent(RouteStatusRoutingQualityWindow, time.Time{})
		report.RoutingQuality = computeRoutingQualityMetricsFromRecords(recent)
	}
	if sc == nil {
		return report, nil
	}

	cooldown := s.routeAttemptTTL()
	activeAttempts := s.activeRouteAttempts(report.GeneratedAt, cooldown)

	entries := make(map[string]*RouteStatusEntry)
	order := make([]string, 0)
	for i, providerName := range sc.ProviderNames() {
		provider, ok := sc.Provider(providerName)
		if !ok {
			continue
		}
		model := provider.Model
		if model == "" {
			model = providerName
		}
		entry, ok := entries[model]
		if !ok {
			entry = &RouteStatusEntry{Model: model, Strategy: "auto"}
			if cached, ok := s.lookupRouteDecision(model); ok {
				entry.LastDecision = cached.decision
				entry.LastDecisionAt = cached.at
				entry.SelectedEndpoint = cached.decision.Endpoint
				entry.SelectedServerInstance = cached.decision.ServerInstance
				entry.Sticky = cached.decision.Sticky
			}
			entries[model] = entry
			order = append(order, model)
		}
		cs := RouteCandidateStatus{
			Provider:       providerName,
			Model:          model,
			ServerInstance: serverinstance.Normalize(provider.BaseURL, provider.ServerInstance),
			Priority:       len(sc.ProviderNames()) - i,
		}
		if attemptCooldown := routeAttemptCandidateCooldown(activeAttempts, providerName, model, cooldown); attemptCooldown != nil {
			cs.Cooldown = attemptCooldown
		}
		cs.Healthy = cs.Cooldown == nil
		entry.Candidates = append(entry.Candidates, cs)
	}

	report.Routes = make([]RouteStatusEntry, 0, len(order))
	for _, model := range order {
		report.Routes = append(report.Routes, *entries[model])
	}

	return report, nil
}

func routeAttemptCandidateCooldown(records []routehealth.Record, providerName, model string, cooldown time.Duration) *CooldownState {
	var newest *routehealth.Record
	for i := range records {
		record := &records[i]
		if record.Key.Provider == "" {
			continue
		}
		if providerName != "" && record.Key.Provider != providerName {
			continue
		}
		if record.Key.Model != "" && model != "" && record.Key.Model != model {
			continue
		}
		if newest == nil || record.RecordedAt.After(newest.RecordedAt) {
			newest = record
		}
	}
	if newest == nil {
		return nil
	}
	return routeAttemptCooldown(*newest, cooldown)
}

// cacheRouteDecision stores a ResolveRoute result keyed by routeKey.
// Called by ResolveRoute after a successful resolution.
func (s *service) cacheRouteDecision(routeKey string, dec *RouteDecision) {
	if routeKey == "" || dec == nil {
		return
	}
	s.lastDecisionMu.Lock()
	defer s.lastDecisionMu.Unlock()
	if s.lastDecisionCache == nil {
		s.lastDecisionCache = make(map[string]lastDecisionEntry)
	}
	s.lastDecisionCache[routeKey] = lastDecisionEntry{
		decision: dec,
		at:       time.Now(),
	}
}

// lookupRouteDecision retrieves a cached decision for routeKey.
func (s *service) lookupRouteDecision(routeKey string) (lastDecisionEntry, bool) {
	s.lastDecisionMu.RLock()
	defer s.lastDecisionMu.RUnlock()
	if s.lastDecisionCache == nil {
		return lastDecisionEntry{}, false
	}
	e, ok := s.lastDecisionCache[routeKey]
	return e, ok
}

package fizeau

import (
	"context"
	"errors"
	"fmt"
	"strings"
	"time"

	"github.com/DocumentDrivenDX/fizeau/internal/harnesses"
	"github.com/DocumentDrivenDX/fizeau/internal/modelcatalog"
	"github.com/DocumentDrivenDX/fizeau/internal/provider/utilization"
	"github.com/DocumentDrivenDX/fizeau/internal/routing"
)

var loadRoutingCatalog = modelcatalog.Default

// ResolveRoute resolves an under-specified RouteRequest to a concrete
// (Harness, Provider, Model) decision per CONTRACT-003.
//
// The implementation delegates to internal/routing.Resolve — the single
// routing engine that consolidates DDx-side harness-tier ranking and
// fiz-side provider failover ordering.
func (s *service) ResolveRoute(ctx context.Context, req RouteRequest) (*RouteDecision, error) {
	if err := ValidatePowerBounds(req.MinPower, req.MaxPower); err != nil {
		return nil, err
	}
	if err := ValidateRole(req.Role); err != nil {
		return nil, err
	}
	if err := ValidateCorrelationID(req.CorrelationID); err != nil {
		return nil, err
	}
	if req.Harness != "" && req.Model != "" {
		canonical := harnesses.ResolveHarnessAlias(req.Harness)
		if !s.registry.Has(canonical) {
			return nil, fmt.Errorf("unknown harness %q", req.Harness)
		}
		cfg, _ := s.registry.Get(canonical)
		if err := validateExplicitHarnessModel(canonical, cfg, req.Model, req.Provider); err != nil {
			return nil, err
		}
	}
	s.ensurePrimaryQuotaRefresh(ctx, quotaRefreshAsync)
	cat := serviceRoutingCatalog()
	profile := req.Profile
	powerPolicy := routePowerPolicyForRequest(cat, req)
	modelRef := req.ModelRef
	providerPreference, err := providerPreferenceForProfile(cat, profile)
	if err != nil {
		return &RouteDecision{
			RequestedProfile: req.Profile,
			PowerPolicy:      powerPolicy,
		}, err
	}
	in := s.buildRoutingInputsWithCatalog(ctx, cat)

	resolvedModel, modelCandidates, modelErr := s.resolveModelConstraint(req.Harness, req.Provider, req.Model, in, cat)
	if modelErr != nil {
		result := &RouteDecision{
			RequestedProfile: req.Profile,
			PowerPolicy:      powerPolicy,
			Candidates:       modelCandidates,
		}
		s.annotateRouteDecisionEvidence(result)
		return result, publicRoutingError(modelErr, result.Candidates)
	}

	rReq := routing.Request{
		Profile:               profile,
		ModelRef:              modelRef,
		Model:                 resolvedModel,
		Provider:              req.Provider,
		Harness:               req.Harness,
		Reasoning:             effectiveReasoningString(req.Reasoning),
		Permissions:           req.Permissions,
		ProviderPreference:    providerPreference,
		EstimatedPromptTokens: req.EstimatedPromptTokens,
		RequiresTools:         req.RequiresTools,
		CorrelationID:         req.CorrelationID,
	}
	rReq.MinPower, rReq.MaxPower = routePowerBoundsForRequest(req, powerPolicy)
	s.applyRouteAttemptCooldowns(&in)
	dec, err := routing.Resolve(rReq, in)
	if err != nil {
		if escalated, edec, eerr := escalateProfileLadder(rReq, in, err); escalated {
			dec = edec
			err = eerr
		}
	}
	result := routeDecisionFromInternal(dec)
	if err != nil {
		if result == nil {
			result = &RouteDecision{}
		}
		result.RequestedProfile = req.Profile
		result.PowerPolicy = powerPolicy
		s.annotateRouteDecisionEvidence(result)
		return result, publicRoutingError(err, result.Candidates)
	}
	s.applyStickyRouteLease(req.CorrelationID, result)
	if result != nil && result.Endpoint == "" {
		_, endpoint, _ := splitEndpointProviderRef(result.Provider)
		result.Endpoint = endpoint
	}
	s.annotateRouteDecisionEvidence(result)
	// Cache the decision so RouteStatus can surface LastDecision.
	if result != nil {
		result.RequestedProfile = req.Profile
		result.PowerPolicy = powerPolicy
		result.Model = resolveSubprocessModelAlias(result.Harness, result.Model)
		result.Power = catalogPowerForModel(cat, result.Model)
	}
	s.cacheRouteDecision(req.Model, result)
	return result, nil
}

func routeDecisionFromInternal(dec *routing.Decision) *RouteDecision {
	if dec == nil {
		return nil
	}
	return &RouteDecision{
		Harness:        dec.Harness,
		Provider:       dec.Provider,
		Endpoint:       dec.Endpoint,
		ServerInstance: dec.ServerInstance,
		Model:          dec.Model,
		Reason:         dec.Reason,
		Candidates:     routeCandidatesFromInternal(dec.Candidates),
	}
}

func routeCandidatesFromInternal(candidates []routing.Candidate) []RouteCandidate {
	if len(candidates) == 0 {
		return nil
	}
	out := make([]RouteCandidate, len(candidates))
	for i, candidate := range candidates {
		out[i] = routeCandidateFromInternal(candidate)
	}
	return out
}

func routeCandidateFromInternal(candidate routing.Candidate) RouteCandidate {
	return RouteCandidate{
		Harness:            candidate.Harness,
		Provider:           candidate.Provider,
		Endpoint:           candidate.Endpoint,
		ServerInstance:     candidate.ServerInstance,
		Model:              candidate.Model,
		Score:              candidate.Score,
		CostUSDPer1kTokens: candidate.CostUSDPer1kTokens,
		CostSource:         candidate.CostSource,
		Eligible:           candidate.Eligible,
		Reason:             candidate.Reason,
		FilterReason:       publicFilterReason(candidate),
		ContextLength:      candidate.ContextLength,
		ContextSource:      candidate.ContextSource,
		Components: RouteCandidateComponents{
			Power:            candidate.Power,
			Cost:             candidate.CostUSDPer1kTokens,
			CostClass:        candidate.CostClass,
			LatencyMS:        candidate.LatencyMS,
			SpeedTPS:         candidate.SpeedTPS,
			Utilization:      candidate.Utilization,
			SuccessRate:      candidate.SuccessRate,
			QuotaOK:          candidate.QuotaOK,
			QuotaPercentUsed: candidate.QuotaPercentUsed,
			QuotaTrend:       candidate.QuotaTrend,
			Capability:       capabilityScoreForCostClass(candidate.CostClass),
			ContextHeadroom:  candidate.ContextHeadroom,
			StickyAffinity:   candidate.StickyAffinity,
		},
	}
}

func (s *service) annotateRouteDecisionEvidence(decision *RouteDecision) {
	if s == nil || decision == nil {
		return
	}
	decision.Utilization = s.routeUtilizationEvidence(decision.Provider, decision.ServerInstance, decision.Endpoint, decision.Model)
	for i := range decision.Candidates {
		decision.Candidates[i].Utilization = s.routeUtilizationEvidence(
			decision.Candidates[i].Provider,
			decision.Candidates[i].ServerInstance,
			decision.Candidates[i].Endpoint,
			decision.Candidates[i].Model,
		)
	}
}

func (s *service) routeUtilizationEvidence(provider, serverInstance, endpoint, model string) RouteUtilizationState {
	if s == nil || s.routeUtilization == nil {
		return RouteUtilizationState{}
	}
	keyProvider := strings.TrimSpace(provider)
	keyServerInstance := strings.TrimSpace(serverInstance)
	keyEndpoint := strings.TrimSpace(endpoint)
	if base, ep, ok := splitEndpointProviderRef(keyProvider); ok {
		keyProvider = base
		if keyEndpoint == "" {
			keyEndpoint = ep
		}
	}
	if keyServerInstance == "" {
		keyServerInstance = keyEndpoint
	}
	sample, ok := s.routeUtilization.Sample(keyProvider, keyServerInstance, model)
	if !ok && keyEndpoint != "" && keyEndpoint != keyServerInstance {
		sample, ok = s.routeUtilization.Sample(keyProvider, keyEndpoint, model)
	}
	if !ok {
		return RouteUtilizationState{}
	}
	return routeUtilizationStateFromSample(sample)
}

func routeUtilizationStateFromSample(sample utilization.EndpointUtilization) RouteUtilizationState {
	out := RouteUtilizationState{
		Source:     string(sample.Source),
		Freshness:  string(sample.Freshness),
		ObservedAt: sample.ObservedAt,
	}
	if sample.ActiveRequests != nil {
		out.ActiveRequests = utilization.Int(*sample.ActiveRequests)
	}
	if sample.QueuedRequests != nil {
		out.QueuedRequests = utilization.Int(*sample.QueuedRequests)
	}
	if sample.MaxConcurrency != nil {
		out.MaxConcurrency = utilization.Int(*sample.MaxConcurrency)
	}
	if sample.CacheUsage != nil {
		v := *sample.CacheUsage
		out.CachePressure = &v
	}
	if out.CachePressure == nil && sample.MaxConcurrency != nil && *sample.MaxConcurrency > 0 {
		total := 0
		if sample.ActiveRequests != nil {
			total += *sample.ActiveRequests
		}
		if sample.QueuedRequests != nil {
			total += *sample.QueuedRequests
		}
		pressure := float64(total) / float64(*sample.MaxConcurrency)
		out.CachePressure = &pressure
	}
	return out
}

// publicFilterReason maps the typed FilterReason emitted by the internal
// routing engine to the public FilterReason* string constant. The internal
// constants are defined to share string values with the public surface, so
// this is a one-line passthrough — there is no string parsing.
func publicFilterReason(c routing.Candidate) string {
	if c.Eligible {
		return ""
	}
	return string(c.FilterReason)
}

package fizeau

import (
	"path/filepath"
	"sync"
	"sync/atomic"
	"time"

	agentcore "github.com/DocumentDrivenDX/fizeau/internal/core"
	"github.com/DocumentDrivenDX/fizeau/internal/harnesses"
	"github.com/DocumentDrivenDX/fizeau/internal/session"
)

// serviceSessionLog is the service-owned writer that persists the session
// lifecycle records (session.start + session.end) for one Execute call. It
// is constructed in runExecute after the route is resolved and torn down in
// a defer on the same goroutine. Sub-paths (runNative, runSubprocess, ...)
// emit the terminal event through finalizeAndEmit, which delegates here to
// keep the session log in sync with the public event stream.
type serviceSessionLog struct {
	logger    *session.Logger
	path      string
	sessionID string
	decision  RouteDecision
	override  *overrideContext
	endOnce   sync.Once
	endWrote  atomic.Bool
	closeOnce sync.Once

	progressMu     sync.Mutex
	lastProgressAt time.Time
}

// openSessionLog creates the session-log writer for req and emits the
// session.start record. A nil-or-empty req.SessionLogDir yields a no-op
// writer so callers don't need to branch on whether logging is enabled.
func (s *service) openSessionLog(req ServiceExecuteRequest, decision RouteDecision, sessionID string) *serviceSessionLog {
	if req.SessionLogDir == "" || sessionID == "" {
		return &serviceSessionLog{}
	}
	logger := session.NewLogger(req.SessionLogDir, sessionID)
	sl := &serviceSessionLog{
		logger:    logger,
		path:      filepath.Join(req.SessionLogDir, sessionID+".jsonl"),
		sessionID: sessionID,
		decision:  decision,
	}
	// CONTRACT-003: echo top-level Role + CorrelationID into the
	// session-log header (one line per session). Top-level wins over
	// any caller Metadata entry under the reserved keys.
	headerMeta := metaWithRoleAndCorrelation(req.Metadata, req.Role, req.CorrelationID)
	start := session.SessionStartData{
		Provider:               s.providerTypeLabel(decision.Provider),
		Model:                  decision.Model,
		SelectedProvider:       decision.Provider,
		SelectedEndpoint:       decision.Endpoint,
		SelectedServerInstance: decision.ServerInstance,
		SelectedRoute:          req.SelectedRoute,
		Sticky: session.RoutingStickyState{
			KeyPresent:     req.CorrelationID != "",
			Assignment:     decision.Sticky.Assignment,
			ServerInstance: decision.Sticky.ServerInstance,
			Reason:         decision.Sticky.Reason,
			Bonus:          decision.Sticky.Bonus,
		},
		Utilization: session.RoutingUtilizationState{
			Source:         decision.Utilization.Source,
			Freshness:      decision.Utilization.Freshness,
			ActiveRequests: decision.Utilization.ActiveRequests,
			QueuedRequests: decision.Utilization.QueuedRequests,
			MaxConcurrency: decision.Utilization.MaxConcurrency,
			CachePressure:  decision.Utilization.CachePressure,
			ObservedAt:     decision.Utilization.ObservedAt,
		},
		RequestedHarness:  req.Harness,
		ResolvedHarness:   decision.Harness,
		HarnessSource:     harnessSource(req),
		RequestedModel:    req.Model,
		RequestedModelRef: req.ModelRef,
		ResolvedModelRef:  req.ResolvedModelRef,
		ResolvedModel:     decision.Model,
		Reasoning:         req.Reasoning,
		WorkDir:           req.WorkDir,
		MaxIterations:     req.MaxIterations,
		Prompt:            req.Prompt,
		SystemPrompt:      req.SystemPrompt,
		Metadata:          headerMeta,
	}
	logger.Emit(agentcore.EventSessionStart, start)
	return sl
}

// writeEnd records the terminal session.end event. It is idempotent: the
// first call wins. Callers should invoke this whenever a harnesses.FinalData
// is produced — finalizeAndEmit threads it together with the public-stream
// emit so the two views stay consistent.
func (sl *serviceSessionLog) writeEnd(req ServiceExecuteRequest, meta map[string]string, final harnesses.FinalData) {
	if sl == nil || sl.logger == nil {
		return
	}
	sl.endOnce.Do(func() {
		sl.endWrote.Store(true)
		end := session.SessionEndData{
			Status:           harnessStatusToCoreStatus(final.Status),
			Output:           final.FinalText,
			Tokens:           finalUsageToCoreTokens(final.Usage),
			DurationMs:       final.DurationMS,
			SelectedRoute:    req.SelectedRoute,
			SelectedEndpoint: sl.decision.Endpoint,
			Sticky: session.RoutingStickyState{
				KeyPresent:     req.CorrelationID != "",
				Assignment:     sl.decision.Sticky.Assignment,
				ServerInstance: sl.decision.Sticky.ServerInstance,
				Reason:         sl.decision.Sticky.Reason,
				Bonus:          sl.decision.Sticky.Bonus,
			},
			Utilization: session.RoutingUtilizationState{
				Source:         sl.decision.Utilization.Source,
				Freshness:      sl.decision.Utilization.Freshness,
				ActiveRequests: sl.decision.Utilization.ActiveRequests,
				QueuedRequests: sl.decision.Utilization.QueuedRequests,
				MaxConcurrency: sl.decision.Utilization.MaxConcurrency,
				CachePressure:  sl.decision.Utilization.CachePressure,
				ObservedAt:     sl.decision.Utilization.ObservedAt,
			},
			RequestedHarness:  req.Harness,
			ResolvedHarness:   "",
			HarnessSource:     harnessSource(req),
			RequestedModel:    req.Model,
			RequestedModelRef: req.ModelRef,
			ResolvedModelRef:  req.ResolvedModelRef,
			Reasoning:         req.Reasoning,
			Metadata:          meta,
			Error:             final.Error,
		}
		if final.CostUSD > 0 {
			cost := final.CostUSD
			end.CostUSD = &cost
		}
		if final.RoutingActual != nil {
			end.ResolvedHarness = final.RoutingActual.Harness
			end.Model = final.RoutingActual.Model
			end.SelectedProvider = final.RoutingActual.Provider
			if final.RoutingActual.ServerInstance != "" {
				end.SelectedServerInstance = final.RoutingActual.ServerInstance
			}
			end.ResolvedModel = final.RoutingActual.Model
			end.AttemptedProviders = append([]string(nil), final.RoutingActual.FallbackChainFired...)
			if len(end.AttemptedProviders) > 1 {
				end.FailoverCount = len(end.AttemptedProviders) - 1
			}
		}
		if end.SelectedServerInstance == "" {
			end.SelectedServerInstance = sl.decision.ServerInstance
		}
		sl.logger.Emit(agentcore.EventSessionEnd, end)
	})
}

// writeEvent persists a raw agent event to the session log. Used by the
// native loop callback to capture llm.request / llm.response / tool.call /
// compaction.* events so kept-sandbox bundles preserve a complete trace
// for benchmark reruns and post-mortem debugging. session.start and
// session.end are skipped because writeStart/writeEnd own those records and
// enrich them with service-side routing fields the loop does not see.
func (sl *serviceSessionLog) writeEvent(ev agentcore.Event) {
	if sl == nil || sl.logger == nil {
		return
	}
	switch ev.Type {
	case agentcore.EventSessionStart, agentcore.EventSessionEnd,
		agentcore.EventOverride, agentcore.EventRejectedOverride:
		return
	}
	sl.logger.Write(ev)
}

// writeOverrideEvent persists an override or rejected_override payload to
// the session log so windowed reporting (UsageReport, ADR-006 §5) can
// recompute routing-quality across restarts and beyond the in-memory
// ring's bounded retention. eventType is one of ServiceEventTypeOverride
// / ServiceEventTypeRejectedOverride.
func (sl *serviceSessionLog) writeOverrideEvent(eventType string, payload ServiceOverrideData) {
	if sl == nil || sl.logger == nil {
		return
	}
	payload.SessionID = sl.sessionID
	sl.logger.Emit(agentcore.EventType(eventType), payload)
}

// close flushes the underlying file. Safe to call multiple times.
func (sl *serviceSessionLog) close() {
	if sl == nil || sl.logger == nil {
		return
	}
	sl.closeOnce.Do(func() {
		_ = sl.logger.Close()
	})
}

// endWritten reports whether writeEnd has already recorded a terminal event.
func (sl *serviceSessionLog) endWritten() bool {
	if sl == nil {
		return false
	}
	return sl.endWrote.Load()
}

// persistRejectedOverride writes a session.start + rejected_override pair
// to a freshly-opened session log for sessionID. Used by Execute's
// pre-dispatch rejection branch, which never reaches runExecute and so
// never goes through the normal openSessionLog path. Without this,
// rejected_override events are invisible to UsageReport (which scans
// session logs over a --since window).
//
// The session.start is required by ScanRoutingQuality, which only counts
// log files that include one — and we want this rejection counted in
// TotalRequests so AutoAcceptanceRate reflects reality.
func (s *service) persistRejectedOverride(req ServiceExecuteRequest, sessionID string, payload ServiceOverrideData) {
	if req.SessionLogDir == "" || sessionID == "" {
		return
	}
	sl := s.openSessionLog(req, RouteDecision{}, sessionID)
	if sl == nil || sl.logger == nil {
		return
	}
	defer sl.close()
	sl.writeOverrideEvent(ServiceEventTypeRejectedOverride, payload)
}

// providerTypeLabel maps a configured provider name ("local") to its provider
// type ("lmstudio") when available. Returns the input unchanged if no
// ServiceConfig is attached or the name is not configured. Callers use this
// to populate session-log Provider fields, which historically carry the
// provider *type* rather than the configured name.
func (s *service) providerTypeLabel(name string) string {
	if s == nil || s.opts.ServiceConfig == nil || name == "" {
		return name
	}
	entry, ok := s.opts.ServiceConfig.Provider(name)
	if !ok || entry.Type == "" {
		return name
	}
	return entry.Type
}

// harnessStatusToCoreStatus maps a public harnesses.FinalData.Status string
// to an internal agentcore.Status. Unknown / error-y statuses collapse to
// StatusError so session.end always carries a well-defined status.
func harnessStatusToCoreStatus(status string) agentcore.Status {
	switch status {
	case "success":
		return agentcore.StatusSuccess
	case "iteration_limit":
		return agentcore.StatusIterationLimit
	case "cancelled":
		return agentcore.StatusCancelled
	default:
		return agentcore.StatusError
	}

