	dead := newCountedOpenAIServer(t, http.StatusServiceUnavailable, "", "")
	healthy := newCountedOpenAIServer(t, http.StatusOK, "qwen3.5-27b", "ok")
	expensive := newCountedOpenAIServer(t, http.StatusOK, "qwen3.5-27b", "ok")
