		fmt.Fprintf(os.Stderr, "error: %s\n", err)
		return 1
	}

	models, err := svc.ListModels(context.Background(), filter)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %s\n", err)
		return 1
	}
	if filter.Provider == "" && filter.Harness == "" {
		harnesses, err := svc.ListHarnesses(context.Background())
		if err != nil {
			fmt.Fprintf(os.Stderr, "error: %s\n", err)
			return 1
